$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.IO.Compression.FileSystem
function ReadXml($z,$part){$rd=[IO.StreamReader]::new($z.GetEntry($part).Open());try{$d=[Xml.XmlDocument]::new();$d.LoadXml($rd.ReadToEnd());return ,$d}finally{$rd.Dispose()}}
function Ns($x){$n=[Xml.XmlNamespaceManager]::new($x.NameTable);$n.AddNamespace('w','http://schemas.openxmlformats.org/wordprocessingml/2006/main');$n.AddNamespace('wp','http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing');$n.AddNamespace('a','http://schemas.openxmlformats.org/drawingml/2006/main');$n.AddNamespace('r','http://schemas.openxmlformats.org/officeDocument/2006/relationships');return ,$n}
function TextOf($x,$n){return ($x.SelectNodes('.//w:t',$n)|ForEach-Object {$_.InnerText})-join''}
function Section($x,$n){$a=@();$inside=$false;foreach($e in $x.SelectSingleNode('//w:body',$n).ChildNodes){$t=TextOf $e $n;if($e.LocalName -eq 'p' -and $t -match '^1\.5\.3\s'){$inside=$true};if($inside -and $e.LocalName -eq 'p' -and $t -match '^2\.\s*PHÂN TÍCH'){break};if($inside){$a+=$e}};return ,$a}
function OutsideText($x,$n){$inside=$false;$a=@();foreach($e in $x.SelectSingleNode('//w:body',$n).ChildNodes){$t=TextOf $e $n;if($e.LocalName -eq 'p' -and $t -match '^1\.5\.3\s'){$inside=$true};if($e.LocalName -eq 'p' -and $t -match '^2\.\s*PHÂN TÍCH'){$inside=$false};if(!$inside){$t=($e.SelectNodes('.//w:t[not(ancestor::w:hyperlink[starts-with(@w:anchor,"_Toc")])]',$n)|ForEach-Object {$_.InnerText})-join'';if($t){$a+=$t}}};return $a -join "`n"}
function ImageHashes($nodes,$ns,$rels,$zip){$hashes=@();foreach($e in $nodes){foreach($b in $e.SelectNodes('.//a:blip[@r:embed]',$ns)){$id=$b.GetAttribute('embed',$ns.LookupNamespace('r'));$rel=@($rels.Relationships.Relationship|Where-Object {$_.Id -eq $id})[0];if(!$rel){throw ('Missing image relationship '+$id)};$entry=$zip.GetEntry('word/'+$rel.Target);if(!$entry){throw 'Missing image entry'};$sha=[Security.Cryptography.SHA256]::Create();$s=$entry.Open();try{$hashes+=[BitConverter]::ToString($sha.ComputeHash($s)).Replace('-','')}finally{$s.Dispose();$sha.Dispose()}}};return ,$hashes}
$sourceZip=[IO.Compression.ZipFile]::OpenRead((Join-Path $PSScriptRoot 'source.docx'));$inputZip=[IO.Compression.ZipFile]::OpenRead((Join-Path $PSScriptRoot 'input.docx'));$workingZip=[IO.Compression.ZipFile]::OpenRead((Join-Path $PSScriptRoot 'working.docx'))
try{
$src=ReadXml $sourceZip 'word/document.xml';$old=ReadXml $inputZip 'word/document.xml';$new=ReadXml $workingZip 'word/document.xml';$sn=Ns $src;$on=Ns $old;$nn=Ns $new
$sourceSection=Section $src $sn;$copiedSection=Section $new $nn
$sourceText=($sourceSection|ForEach-Object {TextOf $_ $sn})-join "`n";$copiedText=($copiedSection|ForEach-Object {TextOf $_ $nn})-join "`n"
$sourceRels=ReadXml $sourceZip 'word/_rels/document.xml.rels';$targetRels=ReadXml $workingZip 'word/_rels/document.xml.rels'
$sourceImages=ImageHashes $sourceSection $sn $sourceRels $sourceZip;$copiedImages=ImageHashes $copiedSection $nn $targetRels $workingZip
$allIds=@($new.SelectNodes('//wp:docPr',$nn)|ForEach-Object {$_.id});$duplicateIds=@($allIds|Group-Object|Where-Object {$_.Count -gt 1})
$sourceTables=@($sourceSection|Where-Object {$_.LocalName -eq 'tbl'});$targetTables=@($copiedSection|Where-Object {$_.LocalName -eq 'tbl'})
$tableStructure=$true;for($i=0;$i -lt $sourceTables.Count;$i++){if($sourceTables[$i].SelectNodes('.//w:tr',$sn).Count -ne $targetTables[$i].SelectNodes('.//w:tr',$nn).Count -or $sourceTables[$i].SelectNodes('.//w:tc',$sn).Count -ne $targetTables[$i].SelectNodes('.//w:tc',$nn).Count){$tableStructure=$false}}
$targetPath=Join-Path (Split-Path (Split-Path $PSScriptRoot)) 'src\Docs\BaoCaoDoAn3_CapNhat_2_2_1_TrangDoc.docx'
$current=[IO.FileStream]::new($targetPath,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::ReadWrite);$sha=[Security.Cryptography.SHA256]::Create();try{$targetHash=[BitConverter]::ToString($sha.ComputeHash($current)).Replace('-','')}finally{$sha.Dispose();$current.Dispose()}
$result=[ordered]@{textIdentical=($sourceText -ceq $copiedText);tables=$targetTables.Count;images=$copiedImages.Count;imagesByteIdentical=(($sourceImages -join ',') -ceq ($copiedImages -join ','));tableStructureIdentical=$tableStructure;outsideSectionTextPreserved=((OutsideText $old $on) -ceq (OutsideText $new $nn));duplicateDrawingIds=$duplicateIds.Count;sequenceDiagramsPreserved=@($new.SelectNodes('//wp:docPr',$nn)|Where-Object {$_.name -like 'UnifiedSequence_*'}).Count;targetUnchangedSinceSnapshot=($targetHash -eq (Get-FileHash -LiteralPath (Join-Path $PSScriptRoot 'input.docx')).Hash)}
$result|ConvertTo-Json|Set-Content (Join-Path $PSScriptRoot 'verification.json') -Encoding UTF8;$result|ConvertTo-Json
if(!$result.textIdentical -or !$result.imagesByteIdentical -or !$result.tableStructureIdentical -or !$result.outsideSectionTextPreserved -or $result.duplicateDrawingIds -or $result.tables -ne 26 -or $result.images -ne 25 -or $result.sequenceDiagramsPreserved -ne 40 -or !$result.targetUnchangedSinceSnapshot){throw 'Verification failed'}
}finally{$workingZip.Dispose();$inputZip.Dispose();$sourceZip.Dispose()}
